use consultation;

-- suppression avec réinitialisation de la valeur de l'auto-incrément
truncate annonce;


insert into annonce (nom, description, date, url, affiche) values
       ('Édition autonale des 4 saisons d\'Amiens-métropole',
        '<p><strong><em>Horaires et distances des courses (&agrave; confirmer)</em></strong></p>\n<p><strong>09h15</strong>&nbsp;5 Km d&eacute;couverte &Eacute;preuve ouverte &agrave; partir de la cat&eacute;gorie Minimes, coureurs licenci&eacute;s ou non licenci&eacute;s.</p>\n<p><strong>10h00</strong> 10 Km des as Coureurs en moins de 45 minutes. Tous les temps (m&ecirc;me sup&eacute;rieurs &agrave; 45\'00) sont pris en compte. &Eacute;preuve ouverte &agrave; partir de la cat&eacute;gorie Cadets, coureurs licenci&eacute;s ou non licenci&eacute;s.</p>\n<p><strong>11h00</strong>&nbsp;10 Km des joggers &Eacute;preuve ouverte &agrave; partir de la cat&eacute;gorie Cadets, coureurs licenci&eacute;s ou non licenci&eacute;s. Joggers du dimanche, d&eacute;butants ou confirm&eacute;s en&nbsp;45 minutes et plus</p>\n<p><strong><em>Les 3 courses de 5 et 10 km sont inscrites au challenge d&eacute;partemental de la Somme.</em></strong></p>\n<p><strong><em>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: #e03e2d;\">&nbsp;Course &agrave; l</span></em></strong><span style=\"color: #e03e2d;\"><strong>abel sur cette &eacute;dition, qualificative pour les championnats de France</strong></span></p>\n<p><strong><em>Inscriptions aux courses</em></strong></p>\n<p>L\'inscription vous donne la possibilit&eacute; de participer &agrave; l\'ensemble des courses propos&eacute;es &nbsp;(5 Km, 10 Km populaire et 10 Km des as)</p>\n<p>Elle s\'effectue&nbsp;<strong>en ligne</strong>&nbsp;&agrave; partir de la plateforme d\'inscription en ligne de klikego. Le lien permettant de vous inscrire sera affich&eacute; sur notre site et sur le site de Courses 80 d&egrave;s que les inscriptions seront ouvertes.</p>\n<p>Toutes les informations de tarifs, dates limites d\'inscription, etc... figurent sur le plateforme d\'inscriptions ou&nbsp; sur notre site.</p>\n<p><strong>Important : Aucune inscription sur place et aucune inscription apr&egrave;s la cl&ocirc;ture des inscriptions en ligne</strong></p>\n<p>Toutes les &eacute;preuves courues se font avec le m&ecirc;me dossard et la m&ecirc;me puce de chronom&eacute;trie coll&eacute;e au dossard.</p>\n<p><strong><em>Tarifs</em></strong></p>\n<p><strong>10&nbsp;euros</strong>&nbsp;(frais d\'inscription compris)&nbsp;pour tous les coureurs sauf si vous &ecirc;tre licenci&eacute; FFA.&nbsp;</p>\n<p><strong>8&nbsp;euros</strong>&nbsp;(frais d\'inscription compris)&nbsp;pour les licenci&eacute;s FFA</p>\n<p><strong>gratuit</strong>&nbsp;si vous &ecirc;tes licenci&eacute; &agrave; l\'Amicale du Val de Somme</p>\n<p><strong>3,8 euros&nbsp;</strong>(frais d\'inscription compris) pour les minimes, uniquement autoris&eacute;s &agrave; courir le 5km</p>\n<p>L\'achat du Pack 4 &eacute;ditions + 4 m&eacute;dailles est encore possible.</p>\n<p>&nbsp;</p>',
        '2026-11-08', 'https://www.valdesomme.fr/4saisons/', 'logo4saisons.jpg'),
       ('Semi du Val d\'Ancre (coquelicot)',
        '<p><strong>DIMANCHE 13 SEPTEMBRE 2026<br>AU STADE VELODROME D&rsquo;ALBERT&nbsp;</strong></p>\n<p>COURSE / TRAIL:</p>\n<ul>\n<li>Le Semi-Marathon du Val d&rsquo;Ancre TRAIL (Coquelicot)</li>\n<li>Airbus Trail 19km</li>\n<li>Albert Trail D&eacute;couverte 5 km</li>\n<li>Marche Loisir km / 13.5 km</li>\n</ul>\n<p>DEPARTS :&nbsp;</p>\n<ul>\n<li>&nbsp;9h pour le semi&nbsp;</li>\n<li>&nbsp;9h15 pour le trail courses80</li>\n</ul>\n<p>Informations : 06.46 175061</p>\n<p><br>R&eacute;compenses pour tous&nbsp;</p>',
        '2026-09-13', 'https://www.facebook.com/p/AMAAC-Albert-M%C3%A9aulte-A%C3%A9rospatiale-100077536203910/',
        'albert.jpg'),
       ('Corrida d\'Argoeuves',
        '<p>Seconde &eacute;dition de la corrida d\'Argoeuvres</p>\n<p>Distance : 5 km</p>\n<p>D&eacute;part : 15 heures</p>\n<p>Label : Bronze FFA</p>\n<p>Renseignement :</p>\n<p><strong>Cl&eacute;ment BOCQUILLON</strong></p>\n<div><strong>Amiens M&eacute;tropole Sports Events</strong></div>\n<div><strong>T&eacute;l : 07.77.90.05.88</strong></div>\n<div>\n<div><strong>Mail : <a href=\"mailto:amiensmetropolesportsevents@gmail.com\" target=\"_blank\" rel=\"noopener\">amiensmetropolesportsevents@gmail.com</a></strong></div>\n</div>\n<p>&nbsp;</p>',
        '2026-12-13', '', 'Argoeuves.png'),
       ('Les Virades de l\'Espoir',
        '<p>Epreuves ouvertes &agrave; tous, licenci&eacute;s ou non (PPS obligatoire), comp&eacute;titeurs ou joggers.</p>\r\n<ul>\r\n<li>10 km : Une grande boucle de 10 km avec une c&ocirc;te au 3&egrave;me kilom&egrave;tre suivie d\'une descente rapide. Virage en &eacute;pingle &agrave; cheveux et pente raide mais courte, juste avant l\'arriv&eacute;e au stade. Course inscrite au challenge Courses 80</li>\r\n<li>D&eacute;fi &laquo;&nbsp;<em>Courir 5 km pour Vaincre la Mucoviscidose&nbsp;&raquo;.&nbsp;</em>Une seule c&ocirc;te au 4&egrave;me kilom&egrave;tre, pour remonter au stade. Course inscrite au challenge&nbsp; Courses 80.</li>\r\n</ul>\r\n<p>Vous avez la possibilit&eacute; de participer au deux &eacute;preuves pour le m&ecirc;me tarif</p>\r\n<p>&nbsp;</p>',
        '2026-09-27', 'https://uscathle.org/', 'virades.png'),
       ('Trail des Crac\'s à Conty',
        '<p>Distances : 15, 25, 35 et 42 km</p>\r\n<p>Courses enfants</p>\r\n<p>Marche 10 Km</p>', '2026-10-18',
        'https://www.facebook.com/profile.php?id=61558715168924&locale=fr_FR', 'conty.jpg'),
       ('100km, Marathon et Semi-Marathon du Val de Somme',
        '<p><strong>Championnats de France<br>FFA 2026-2027 des 100KM</strong></p>\n<p>Consultez les fiches de chaque &eacute;preuve sur le site www.100kmdelasomme.com</p>',
        '2026-10-03', 'https://100kmdelasomme.com/', '100km.png'),
       ('Le Trail des Sentiers Maudits',
        '<p>🌙🏃&zwj;♂️&nbsp;<strong>Le Trail des Sentiers Maudits revient pour sa 2ᵉ &eacute;dition !</strong>&nbsp;🏃&zwj;♀️🌙</p>\n<p>Apr&egrave;s le succ&egrave;s de la premi&egrave;re &eacute;dition, le&nbsp;<strong>Trail des Sentiers Maudits</strong>&nbsp;vous donne rendez-vous pour une&nbsp;<strong>soir&eacute;e et une nuit</strong>&nbsp;plac&eacute;es sous le signe du d&eacute;passement de soi, de l\'aventure et de la convivialit&eacute;.</p>\n<p>Au programme :</p>\n<p>✨&nbsp;<strong>De nouveaux parcours</strong>&nbsp;encore plus surprenants.</p>\n<p>🎭&nbsp;<strong>De nouvelles animations</strong>&nbsp;pour faire vibrer coureurs et spectateurs.</p>\n<p>🏅&nbsp;<strong>De nouvelles r&eacute;compenses</strong>&nbsp;pour c&eacute;l&eacute;brer vos exploits.</p>\n<p>🔦 Une exp&eacute;rience unique &agrave; travers les sentiers, entre ombre, lumi&egrave;re et myst&egrave;re.</p>\n<p>💀 Des surprises vous attendent tout au long du parcours des Sentiers Maudits.</p>\n<p>Que vous soyez traileur confirm&eacute;, amateur de sensations nocturnes ou simplement curieux de vivre une aventure hors du commun, cette deuxi&egrave;me &eacute;dition promet d\'&ecirc;tre encore plus m&eacute;morable.</p>\n<p>📅 Pr&eacute;parez votre lampe frontale pour une soir&eacute;e inoubliable !</p>',
        '2026-10-24', 'https://www.facebook.com/LeTraildesSentiersMaudits/', 'hangest.jpg'),
       ('La Cro Magnon',
        '<h1><strong>La Cro Magnon c\'est :&nbsp;</strong></h1>\r\n<h2><strong>- Une ambiance conviviable</strong></h2>\r\n<h4><strong>- 2 trails :&nbsp;</strong>1 tombola pour les coureurs (N&deg; de dossards)</h4>\r\n<p>- 15,8 km,inscription suivant cat&eacute;gorie d\'age de la FFA, 1 lot par coureur, 16&euro; + commission site</p>\r\n<p>- 8 km,&nbsp;inscription suivant cat&eacute;gorie d\'ade de la FFA, 1 lot par coureur, 12&euro; + commission site</p>\r\n<p><strong>-&nbsp;3 parcours de marche pour sastifaire tous les marcheurs du d&eacute;butant au plus exp&eacute;riment&eacute;</strong></p>\r\n<p>- 8&nbsp;km,&nbsp;1 ravitaillement &agrave; mi parcours, un lot + &nbsp;ravitaillement en fin de parcours, 6&euro; + commission site</p>\r\n<p>- 11&nbsp;km,1 ravitaillement &agrave; mi parcours, un lot +&nbsp;ravitaillement en fin de parcours, 6&euro; + commission site</p>\r\n<p>- 16&nbsp;km,&nbsp;2&nbsp;ravitaillements r&eacute;partis sur le parcours, un lot + ravitaillement en fin de parcours, 7&euro; + commission site</p>\r\n<p><strong>-&nbsp;2 courses enfants (500 m pour les 5-6&nbsp;ans &amp; 1000m pour les 7-9 ans) inscription sur place (telecharger l\'autorisation parentale)</strong></p>\r\n<p>-&nbsp;<strong>La possibilit&eacute; de se restaurer sur place , buvette et repas BBQ ( repas BBQ, inscription obligatoire sur Klikego)</strong></p>\r\n<p>- Quelques places de camping pour ceux ui d&eacute;sirent arriver le samedi (r&eacute;servation obligatoire)</p>',
        '2026-08-30', 'https://www.facebook.com/LaCromagnon/?locale=fr_FR', 'drucat.jpg'),
       ('La Corrid\'Halloween de Montdidier',
        '<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\">Apr&egrave;s le succ&egrave;s de l&rsquo;an dernier, nous sommes ravis de vous annoncer le grand retour de notre Corrid&rsquo;Halloween ! <span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/td7/1/16/1f47b.png\" alt=\"👻\" width=\"16\" height=\"16\"></span></div>\n<div dir=\"auto\">&nbsp;</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t7e/1/16/1f4c5.png\" alt=\"📅\" width=\"16\" height=\"16\"></span> Rendez-vous le samedi 31 octobre 2026</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t2d/1/16/1f4cd.png\" alt=\"📍\" width=\"16\" height=\"16\"></span> D&eacute;part : Gymnase Paul Balny (Prieur&eacute;)</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t2d/1/16/1f4cd.png\" alt=\"📍\" width=\"16\" height=\"16\"></span> Repas et remises des r&eacute;compenses : Gymnase Handisport</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tab/1/16/1f3c3_200d_2642.png\" alt=\"🏃&zwj;♂️\" width=\"16\" height=\"16\"></span> Une course festive de 5 km, accessible &agrave; tous !</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\">Que vous soyez coureur r&eacute;gulier, amateur ou simplement venu pour l&rsquo;ambiance, cette course est faite pour vous. D&eacute;guisements, bonne humeur et frissons garantis ! <span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tae/1/16/1f3ad.png\" alt=\"🎭\" width=\"16\" height=\"16\"></span><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tee/1/16/1f578.png\" alt=\"🕸️\" width=\"16\" height=\"16\"></span></div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\n<div dir=\"auto\">L&rsquo;an dernier, vous avez &eacute;t&eacute; nombreux &agrave; r&eacute;pondre pr&eacute;sent, mais aussi nombreux &agrave; &ecirc;tre d&eacute;&ccedil;us de ne pas avoir pu vous inscrire &agrave; temps, alors cette ann&eacute;e, nous avons &eacute;largi notre capacit&eacute; de dossards, on compte encore plus sur vous pour faire vibrer les rues de Montdidier ! <span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t50/1/16/1f525.png\" alt=\"🔥\" width=\"16\" height=\"16\"></span></div>\n<div dir=\"auto\">\n<p>18h45 : course poussin 1500m</p>\n<p>19h00 : course benjamins 3000m</p>\n<p>19h30 : course 5 km en moins de 23 minutes</p>\n<p>20h15 : course&nbsp; 5 km en plus de 23 minutes</p>\n<p>Ouverture des inscriptions en ligne sur la plateforme Klikego le 31 juillet</p>\n<p>&nbsp;</p>\n</div>\n</div>',
        '2026-10-31', 'https://www.facebook.com/lacorridhalloweendemontdidier', 'montdidier.png'),
       ('Corrida de Boves 5KM',
        '<p>COURSE A LABEL BRONZE FFA</p>\r\n<p>Lot aux&nbsp; 1000 premiers inscrits , lors du&nbsp;retrait de votre dossard.&nbsp;</p>\r\n<pre> CHALLENGE COURSE 80&nbsp;</pre>\r\n<p>CHRONOMETRIE COURSE 80 AVEC TEMPS&nbsp;REEL&nbsp;</p>\r\n<p>NOUVEAU PARCOURS&nbsp;2 BOUCLES DE 2.5 KM</p>\r\n<ul>\r\n<li>HORAIRES</li>\r\n</ul>\r\n<p>15h00 course elite</p>\r\n<p>15h20 course populaire</p>\r\n<p>Arriv&eacute;e rue du g&eacute;n&eacute;ral de Gaulle ( &agrave; 100 mt du d&eacute;part)</p>\r\n<ul>\r\n<li>DOSSARDS</li>\r\n</ul>\r\n<p>Retrait la&nbsp;veille chez notre partenaire magasin foul&eacute;es &agrave; Boves de 14h &agrave; 17h&nbsp;</p>\r\n<p>Le jour de la comp&eacute;tition dans la salle des f&ecirc;tes de Boves d&egrave;s 13h - - ne pas venir en voiture.&nbsp;</p>',
        '2026-12-06', 'https://www.facebook.com/courirauchu/', 'boves.jpg'),
       ('Trail des Vidames',
        '<p>Le Trail des Vidames est organis&eacute; le 11 novembre 2026 &agrave; Picquigny par l\'association &laquo; Picquigny Running Club &raquo;</p>\r\n<p>D&eacute;part : 13h30 rue du marais au niveau du Camping Municipal<br>Parcours de +/- 21 km essentiellement sur chemins, sentiers forestiers.<br>Arriv&eacute;e : Salle municipale du groupe scolaire</p>\r\n<p>&nbsp;</p>',
        '2026-11-11', 'http://traildesvidames.free.fr', 'vidames.jpg'),
       ('Corrida de Camon',
        '<p>L&rsquo;US Camon Athl&eacute;tisme organise une corrida nocturne de 5km en centre ville de Camon.</p>\r\n<p>Cette course r&eacute;unira aussi bien les coureurs qui souhaitent courir 5km dans une ambiance festive de No&euml;l, que les coureurs comp&eacute;titeurs qui chercheront &agrave; battre leur record sur 5km.</p>\r\n<p>Une course pour les enfants sera &eacute;galement organis&eacute;e. Une r&eacute;compense sera offerte &agrave; chaque participant.</p>\r\n<p>N&rsquo;h&eacute;sitez pas &agrave; venir profiter de l&rsquo;ambiance de No&euml;l ce samedi 19 D&eacute;cembre 2026 &agrave; la Corrida de Camon ! &raquo;&nbsp;</p>\r\n<div>&nbsp;</div>\r\n<div>Normalement les horaires seront les suivantes :&nbsp;</div>\r\n<div>- Courses enfant &agrave; partir de 16h (certainement 2 courses, en partenariat avec les &eacute;coles)&nbsp;</div>\r\n<div>- Course des &laquo;&nbsp;joggeurs&nbsp;&raquo; &agrave; 18h30&nbsp;</div>\r\n<div>- Course &laquo; &eacute;lite &raquo; &agrave; 19h30&nbsp;</div>',
        '2026-12-19', 'https://www.uscathle.org/', 'camon.jpg'),
       ('5km d\'Amiens-métropole et mile sur route',
        '<p>Le club de l&rsquo;Amicale du Val de Somme organisera donc&nbsp;<strong>le 20 septembre 2026</strong>, au parc de la Hotoie &agrave; Amiens les 5 km d\'Amiens-m&eacute;tropole, &eacute;preuve qualificative en r&eacute;gion pour les championnats de France de 5 km.</p>\r\n<p>Quelques informations &agrave; connaitre :</p>\r\n<ul>\r\n<li>\r\n<p>Parcours plat tr&egrave;s performant (4 boucles de 1,25 km)</p>\r\n</li>\r\n<li>\r\n<p>Label FFA Argent&nbsp;</p>\r\n</li>\r\n<li>\r\n<p>Ouverture des inscriptions en ligne sur klikego pr&eacute;vue d&eacute;but juillet.</p>\r\n</li>\r\n<li>\r\n<p>Retrait des dossards sur place &agrave; partir de 8h30 au gymnase de La Hotoie. Consigne sur place.</p>\r\n</li>\r\n<li>\r\n<p>4 d&eacute;parts successifs pr&eacute;vus pour cette nouvelle &eacute;dition :</p>\r\n</li>\r\n</ul>\r\n<p><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; plus de&nbsp; 27 minutes,</strong></p>\r\n<p><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; entre 21 et 27 minutes,</strong></p>\r\n<p><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; entre 17 et 21 minutes,</strong></p>\r\n<p><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; moins de 17 minutes.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong></p>\r\n<p>Cette comp&eacute;tition est ouverte &agrave; tous (m&ecirc;me aux non licenci&eacute;s)</p>\r\n<p>Deux fa&ccedil;ons de se qualifier aux championnats de France de 5km&nbsp; :</p>\r\n<ol>\r\n<li>Soit faire les minimas \"A\" sur un des 5km &agrave; label dans l\'ann&eacute;e pr&eacute;c&eacute;dente,</li>\r\n<li>Soit faire les minimas \"B\" lors de la demi-finale.</li>\r\n</ol>\r\n<p>Le parcours est tr&egrave;s performant.&nbsp;</p>\r\n<p>Une course de 1 mile (label FFA) sur 1609 m cl&ocirc;turera la matin&eacute;e &agrave; 12 h.</p>',
        '2026-09-20', 'https://www.valdesomme.fr/5km/', '5kmamiens.jpg'),
       ('Les foulées Méaultoise',
        '<p>Distances : 5 et 10 Km</p>\n<p>Horaire : 9H10 et 10h15</p>\n<p>Courses label bronze FFA, qualificatives pour les championnats de France</p>\n<p>Courses enfants</p>',
        '2027-02-07', 'https://www.facebook.com/p/AMAAC-Albert-M%C3%A9aulte-A%C3%A9rospatiale-100077536203910/',
        'meaultes.jpg'),
       ('La Rose Doullennaise',
        '<p>Venez courir pour la&nbsp;bonne cause,ce&nbsp;11 octobre on(r)ose le d&eacute;fi!!&nbsp;</p>\r\n<p>Les fonds r&eacute;colt&eacute;s seront rev&eacute;rs&eacute;s &agrave; l\'association la Rose Doullennais et &agrave; la ligue contre le cancer.&nbsp;</p>\r\n<p>Venez marcher&nbsp;vers la Citadelle de Doullens ou courir&nbsp;sur les chemins de l\'Authie et du doullennais.&nbsp;</p>\r\n<p>D&eacute;part des marcheurs 9h45/10h&nbsp;</p>\r\n<p>D&eacute;part des coureurs 10h30&nbsp;</p>\r\n<p>Inscription sur KLIKEGO obligatoire pour les courses.<br>Possibilit&eacute; de s&rsquo;inscrire sur place pour les marches avec majoration de 1 euro.<br>A partir du 8 ao&ucirc;t jusqu&rsquo;au jeudi 08 octobre 2025 &agrave; minuit, avec paiement s&eacute;curis&eacute; en euros, dans la limite des places disponibles sur KLIKEGO LA ROSE DOULLENNAISE.<br>- Trail 6 kms : 6 euros (6,80)<br>- Trail 15 kms : 10 euros (11)<br>- Marche de 6/11 kms : 5 euros (5,80)</p>\r\n<p>Les enfants de moins de 10 ans accompagn&eacute;s des parents peuvent participer &agrave; la marche gratuitement et les<br>enfants mineurs inscrits seront sous la responsabilit&eacute; d&rsquo;un parent ou d&rsquo;une personne majeure accompagnante.<br>PAS D&rsquo;INSCRIPTION SUR PLACE pour les courses chronom&eacute;tr&eacute;es&nbsp;</p>',
        '2026-10-11', 'https://www.facebook.com/p/La-Rose-Doullennaise-61566794025391/', 'doullens.jpg'),
       ('La CORRID’ASG',
        '<h1>🏃&zwj;♂️ La CORRID&rsquo;ASG revient le dimanche 11 octobre 2026 !</h1>\r\n<p>Apr&egrave;s une premi&egrave;re &eacute;dition couronn&eacute;e de succ&egrave;s en 2024 avec pr&egrave;s de&nbsp;<strong>200 participants</strong>, l&rsquo;Association Sportive de Grivesnes (ASG) est heureuse d&rsquo;annoncer le retour de sa course sur route, organis&eacute;e tous les deux ans.</p>\r\n<p>📍&nbsp;<strong>Nouveau lieu pour cette &eacute;dition : Coullemelle</strong><br>Suite &agrave; l&rsquo;indisponibilit&eacute; de la salle des f&ecirc;tes de Grivesnes, l&rsquo;&eacute;v&eacute;nement est exceptionnellement d&eacute;localis&eacute; &agrave; seulement quelques kilom&egrave;tres, &agrave; la&nbsp;<strong>salle des f&ecirc;tes de Coullemelle</strong>. Ce changement permet surtout de proposer de&nbsp;<strong>nouveaux parcours 100 % route et ultra plats</strong>, particuli&egrave;rement adapt&eacute;s aux coureurs souhaitant se faire plaisir ou aller chercher un chrono.</p>\r\n<h3>🏁 Au programme</h3>\r\n<ul>\r\n<li><strong>10 km</strong>&nbsp;&ndash; parcours 100 % route et ultra plat</li>\r\n<li><strong>5 km</strong>&nbsp;&ndash; parcours 100 % route et ultra plat</li>\r\n<li><strong>Course enfants de 1 km</strong>&nbsp;&ndash; destin&eacute;e aux plus jeunes</li>\r\n</ul>\r\n<h3>📅 Informations pratiques</h3>\r\n<p><strong>Date :</strong>&nbsp;dimanche 11 octobre 2026<br><strong>Lieu :</strong>&nbsp;Salle des f&ecirc;tes de Coullemelle<br><strong>Retrait des dossards :</strong>&nbsp;&agrave; partir de 8h00<br><strong>D&eacute;parts :</strong>&nbsp;horaires communiqu&eacute;s par l&rsquo;organisation<br><strong>Inscriptions :</strong>&nbsp;ouvertes<br><strong>Course adultes :</strong>&nbsp;360 places maximum, soit 180 places sur le 5 km et 180 sur le 10 km<br><strong>Course enfants :</strong>&nbsp;limit&eacute;e &agrave; 40 participants</p>\r\n<p>🏅&nbsp;<strong>Une m&eacute;daille Finisher en m&eacute;tal sera remise &agrave; tous les participants des courses adultes.</strong>&nbsp;Des r&eacute;compenses seront &eacute;galement pr&eacute;vues pour les enfants, ainsi que des podiums pour les trois premiers hommes et femmes du 5 km et du 10 km.</p>\r\n<p>🍔 Pour prolonger la matin&eacute;e dans une ambiance conviviale, des&nbsp;<strong>food trucks sucr&eacute; et sal&eacute;</strong>&nbsp;seront pr&eacute;sents sur place.</p>\r\n<p>L&rsquo;ASG souhaite conserver l&rsquo;esprit qui fait l&rsquo;identit&eacute; de ses &eacute;v&eacute;nements : une course&nbsp;<strong>familiale, conviviale et accessible &agrave; tous</strong>, que l&rsquo;on soit habitu&eacute; au trail ou plut&ocirc;t adepte de la course sur route.</p>\r\n<p>⚠️&nbsp;<strong>Les places &eacute;tant limit&eacute;es, les inscriptions sont &agrave; effectuer rapidement.</strong></p>\r\n<p>🎟️&nbsp;<strong>Inscriptions :</strong></p>\r\n<div><a href=\"https://www.canvaqr.com/RGPfvoN55Y\" target=\"_blank\" rel=\"noopener\">la-corridasg.adeorun.com</a></div>\r\n<p>&nbsp;</p>\r\n<p>📞&nbsp;<strong>Renseignements :</strong>&nbsp;06 70 05 38 29<br>📧&nbsp;<strong>Course enfants :</strong>&nbsp;<a href=\"mailto:asgdegrivesnes@gmail.com\" target=\"_blank\" rel=\"noopener\">asgdegrivesnes@gmail.com</a></p>\r\n<p>L&rsquo;ASG remercie chaleureusement la&nbsp;<strong>commune de Coullemelle</strong>, son&nbsp;<strong>comit&eacute; des f&ecirc;tes</strong>&nbsp;ainsi que l&rsquo;ensemble de ses partenaires pour leur confiance et leur soutien dans l&rsquo;organisation de cette nouvelle &eacute;dition.</p>\r\n<p>📍&nbsp;<strong>Rendez-vous le dimanche 11 octobre &agrave; Coullemelle pour une nouvelle f&ecirc;te du sport !</strong></p>',
        '2026-10-11', NULL, 'grivesnes.png'),
       ('Les Foulées Bleues Decathlon',
        '<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s\">\n<div dir=\"auto\">Parce que la lutte contre les cancers masculins est un enjeu de sant&eacute; publique</div>\n<div dir=\"auto\">l\'Amiens UC Athletisme, l\'association Centropolis avec le soutien de Decathlon Amiens et d\'Amiens Metropole organisent le foul&eacute;es bleues Decathlon le mardi 11 novembre prochain afin de susciter la conversation et briser les tabous autour des cancers masculins.</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s\">\n<div dir=\"auto\">Nous avons besoin de vous tous pour que cet &eacute;v&eacute;nement sportif et caritatif marque les esprits pour sensibiliser, faire de la pr&eacute;vention et r&eacute;colter des fonds pour la recherche.</div>\n</div>\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s\">\n<div dir=\"auto\">Marchons, courons, sensibilisons, agissons le 11 novembre pour la sant&eacute; des hommes !!!!&nbsp;</div>\n<div dir=\"auto\">&nbsp;</div>\n<div dir=\"auto\">\n<p>Les points forts de cette manifestation sportive :</p>\n<ul>\n<li>100% sport sant&eacute; avec un 5km course et marche sur route accessible et ouvert &agrave; tous + une marche rando et Nordique de 10km 100% nature</li>\n<li>Un 2&eacute;me 5km course labelis&eacute; sur un parcours ultra roulant avec chronom&eacute;trage et classement, qualificatif aux championnats de France de 5km pour ne pas mettre de c&ocirc;t&eacute; les coureurs avides de performance. A noter la victoire du champion de France du 5km lors de l&rsquo;&eacute;dition 2026.</li>\n<li>Des courses pour les enfants sur la piste du stade Urbain wallet</li>\n</ul>\n</div>\n</div>',
        '2026-11-11', 'https://www.facebook.com/groups/794502073027550', 'fouleesbleues.png'),
       ('Corrida de Marcelcave',
        '<p><strong>Ne manquez pas l\'&eacute;dition 2026 de la Corrida de Marcelcave !</strong></p>\r\n<p>Pr&eacute;parez-vous &agrave; chausser vos baskets pour un rendez-vous incontournable du calendrier r&eacute;gional ! Conviviale, cette &eacute;dition promet &agrave; nouveau une exp&eacute;rience de course rapide et une ambiance festive pour toute la famille.</p>\r\n<p><strong>Un parcours plat et rapide pour tous les objectifs</strong>&nbsp;</p>\r\n<p>Que vous visiez un record personnel, une qualification pour les Championnats de France de 5 km ou simplement un moment de partage, Marcelcave est le terrain id&eacute;al.</p>\r\n<ul>\r\n<li>\r\n<p><strong>Le 5 km :</strong>&nbsp;un circuit plat de 3 boucles, officiellement mesur&eacute;, avec chaque kilom&egrave;tre indiqu&eacute;. Id&eacute;al pour pulv&eacute;riser votre chrono ou maitriser ses allures&nbsp;! L\'&eacute;preuve compte &eacute;galement pour le&nbsp;<strong>Challenge Courses 80</strong>.</p>\r\n</li>\r\n<li>\r\n<p><strong>Nouveaut&eacute; &mdash; Course Enfants (1 000 m) :</strong>&nbsp;les plus jeunes &agrave; partir de 2020&nbsp;&agrave; 2014)&nbsp; ont aussi leur moment de gloire ! Amenez vos enfants pour partager une v&eacute;ritable apr&egrave;s-midi sportive en famille.</p>\r\n</li>\r\n</ul>\r\n<p>Du comp&eacute;titeur aguerri au coureur occasionnel, la Corrida accueille tous les profils. Venez profiter de l\'&eacute;nergie du peloton et du soutien des spectateurs, quelle que soit votre allure !</p>',
        '2026-11-15', 'https://cercle-olympique-samarien.jimdosite.com/', 'marcelcave.jpg');
